-- Additive, isolated ecosystem foundation. No production records are modified.
CREATE TABLE IF NOT EXISTS ecosystem_notifications (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), recipient_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL CHECK(category IN ('operasional','pesanan','sistem')), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', href TEXT NOT NULL DEFAULT '/dashboard', source_key TEXT, created TEXT NOT NULL, read_at TEXT, UNIQUE(owner,recipient_id,source_key));
CREATE INDEX IF NOT EXISTS ecosystem_notifications_inbox ON ecosystem_notifications(owner,recipient_id,created DESC);
CREATE TABLE IF NOT EXISTS commerce_products (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), sku TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL DEFAULT 'unit', price BIGINT NOT NULL CHECK(price>=0 AND price<=1000000000000), stock INTEGER NOT NULL CHECK(stock>=0), published BOOLEAN NOT NULL DEFAULT FALSE, created TEXT NOT NULL, updated TEXT NOT NULL, UNIQUE(owner,sku));
CREATE INDEX IF NOT EXISTS commerce_products_store ON commerce_products(owner,published,name);
CREATE TABLE IF NOT EXISTS commerce_orders (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), buyer_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES commerce_products(id), product_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0 AND quantity<=10000), unit_price BIGINT NOT NULL CHECK(unit_price>=0), total BIGINT NOT NULL CHECK(total>=0), status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','confirmed','cancelled','completed')), client_request_id TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL, UNIQUE(owner,buyer_id,client_request_id));
CREATE INDEX IF NOT EXISTS commerce_orders_owner_created ON commerce_orders(owner,created DESC);
CREATE INDEX IF NOT EXISTS commerce_orders_buyer_created ON commerce_orders(buyer_id,created DESC);
CREATE TABLE IF NOT EXISTS ledger_accounts (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), code TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('asset','liability','equity','revenue','expense')), active BOOLEAN NOT NULL DEFAULT TRUE, created TEXT NOT NULL, UNIQUE(owner,code));
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), actor_id TEXT NOT NULL REFERENCES users(id), posted_date TEXT NOT NULL, memo TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, UNIQUE(owner,reference));
CREATE INDEX IF NOT EXISTS ledger_entries_owner_date ON ledger_entries(owner,posted_date DESC);
CREATE TABLE IF NOT EXISTS ledger_lines (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES ledger_entries(id) ON DELETE RESTRICT, account_id TEXT NOT NULL REFERENCES ledger_accounts(id), debit BIGINT NOT NULL DEFAULT 0 CHECK(debit>=0), credit BIGINT NOT NULL DEFAULT 0 CHECK(credit>=0), CHECK ((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE INDEX IF NOT EXISTS ledger_lines_account ON ledger_lines(account_id,entry_id);
